"""Reproducible source masks and separate ink/colour layers for issue #119.
Run from project root after placing the files listed in SOURCES.md in source/alchemy/.
No source image or derived PNG is committed. The modest robe repair is a disclosed AI edit.
"""
from pathlib import Path
from PIL import Image, ImageDraw, ImageFilter
import numpy as np, json, sys
src=Path(sys.argv[1] if len(sys.argv)>1 else 'source/alchemy'); out=Path('assets/alchemy'); out.mkdir(parents=True,exist_ok=True)
meta={}
def part(name,file,poly,white=224,black=70):
 im=Image.open(src/file).convert('RGBA')
 if file=='clean-robes.png':im=im.resize((1307,1203),Image.Resampling.LANCZOS)
 mask=Image.new('L',im.size); ImageDraw.Draw(mask).polygon(poly,fill=255)
 a=np.asarray(im)[:,:,3].astype(float)/255*np.asarray(mask)/255
 gray=np.asarray(im.convert('L')).astype(float)
 ink=np.clip((white-gray)/(white-black),0,1)**.85*a
 box=mask.getbbox(); rgba=np.zeros((*gray.shape,4),dtype=np.uint8);rgba[:,:,:3]=[39,38,29];rgba[:,:,3]=(ink*255).astype('uint8')
 Image.fromarray(rgba).crop(box).save(out/(name+'-ink.png'))
 rgba[:,:,:3]=255;rgba[:,:,3]=(a*255).astype('uint8');Image.fromarray(rgba).crop(box).save(out/(name+'-mask.png'))
 meta[name]={'box':list(box),'source':file};print(name,box)
def p(name,poly):part(name,'clean-robes.png' if name.endswith('-body') else 'clothed-pair.png',poly,235,65)
